    /**
     * Method to retrieve the Position via PositionFetchOneSummary
     * @param 	summary PositionFetchOneSummary 
     * @return 	PositionFetchOneResponse
     * @exception ProcessingException - Thrown if processing any related problems
     * @exception IllegalArgumentException 
     */
    public Position getPosition( PositionFetchOneSummary summary ) 
    throws ProcessingException, IllegalArgumentException {
    	
    	if( summary == null )
    		throw new IllegalArgumentException( "PositionFetchOneSummary arg cannot be null" );
    	
    	Position entity = null;
    	
        try {
        	// --------------------------------------
        	// validate the fetch one summary
        	// --------------------------------------    	
        	validator.validate( summary );    
        	
        	// --------------------------------------
        	// use queryGateway to send request to Find a Position
        	// --------------------------------------
        	CompletableFuture<Position> futureEntity = queryGateway.query(new FindPositionQuery( new LoadPositionFilter( summary.getPositionId() ) ), ResponseTypes.instanceOf(Position.class));
        	
        	entity = futureEntity.get();
        }
        catch( Exception exc ) {
            final String errMsg = "Unable to locate Position with id " + summary.getPositionId();
            LOGGER.log( Level.WARNING, errMsg, exc );
            throw new ProcessingException( errMsg, exc );
        }
        finally {
        }        
        
        return entity;
    }


