    /**
     * assign Portfolio on Position
     * @param		command AssignPortfolioToPositionCommand	
     * @exception	ProcessingException
     */     
	public void assignPortfolio( AssignPortfolioToPositionCommand command ) throws ProcessingException {

		// --------------------------------------------
		// load the parent
		// --------------------------------------------
		load( command.getPositionId() );
		
		InvestmentPortfolioService childDelegate 	= InvestmentPortfolioService.getInvestmentPortfolioInstance();
		PositionService parentDelegate = PositionService.getPositionInstance();			
		UUID childId = command.getAssignment().getInvestmentPortfolioId();
		InvestmentPortfolio child = null;
		
		try {
			// --------------------------------------
	    	// best to validate the command now
	    	// --------------------------------------    
	    	validator.validate( command );    

	    	// --------------------------------------
        	// issue the command
        	// --------------------------------------    	
    		commandGateway.sendAndWait( command );

		}
        catch( Throwable exc ) {
			final String msg = "Failed to get InvestmentPortfolio using id " + childId;
			LOGGER.log( Level.WARNING,  msg );
			throw new ProcessingException( msg, exc );
        }
	}

